def round_half_to_even(n):
    if n % 1 == 0.5:
        if n - 2 * int(n / 2) == 0.5:
            return int(n)
        else:
            return int(n) + 1
    else:
        return int(n + 0.5)

def round_half_to_even(n):
    if not isinstance(n, (int, float)):
        raise TypeError("n must be an int or float")
    if n < 0:
        raise ValueError("n must be non-negative")
    return int(2 * round(n * 0.5))

