    def extostr(cls, e, max_level=30, max_path_level=5):
        """
        Format an exception.
        :param e: Any exception instance.
        :type e: Exception
        :param max_level: Maximum call stack level (default 30)
        :type max_level: int
        :param max_path_level: Maximum path level (default 5)
        :type max_path_level: int
        :return The exception readable string
        :rtype str
        """
        # Check if the input is an exception
        if not isinstance(e, Exception):
            raise ValueError("Input must be an exception instance")

        message = str(e)
        ex_type = type(e).__name__

        # If the maximum call stack level is negative, set it to 0
        if max_level < 0:
            max_level = 0

        # If the maximum path level is negative, set it to 0
        if max_path_level < 0:
            max_path_level = 0

        # Handle exceptions without a traceback
        if not hasattr(e, "traceback"):
            return "{} ({})".format(message, ex_type)

        # If the exception has a traceback, iterate through it
        traceback = e.traceback
        if hasattr(traceback, "format_exc"):
            return traceback.format_exc()
        else:
            return "{} ({})".format(message, ex_type)

def extostr(e, max_level=30, max_path_level=5):
    s = []
    level = 0
    while e is not None and level <= max_level:
        s.append(f"{e.__class__.__name__}: {e}")
        if level < max_path_level:
            s.append(f"  File \"{e.filename}\", line {e.lineno}")
        e = e.cause()
        level += 1
    return "".join(s)

