def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expressions applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for arg in args:
        if isinstance(arg, (And, Or)):
            if isinstance(arg.left, arg.right):
                new_args.append(arg.left)
            elif isinstance(arg.left, (Not, Not)):
                if isinstance(arg.left.expr, arg.right):
                    new_args.append(arg.left.expr & arg.right)
            else:
                new_args.append(arg)
        else:
            new_args.append(arg)
    return new_args

