    new_args = []
    for expr in args:
        for old_expr in new_args:
            if expr.replace("~", "").startswith(old_expr) and expr.endswith(old_expr.replace("~", "")):
                new_args.append(expr.replace("~", ""))
                break
        else:
            new_args.append(expr)
    return new_args

def absorb(self, args):
    result = []
    for expr in args:
        # Check if the current expression is a disjunction (|) or conjunction (&)
        if expr.op == '|':
            # If the current expression is a disjunction, check if any of the operands are another disjunction
            for operand in expr.operands:
                if operand.op == '|':
                    # If so, absorb the operands of the operand disjunction into the current disjunction
                    result += operand.operands
                    break
            # If the current disjunction does not contain another disjunction, append it to the result
            else:
                result.append(expr)
        elif expr.op == '&':
            # If the current expression is a conjunction, check if any of the operands are a negation
            for operand in expr.operands:
                if operand.op == '~':
                    # If so, apply negative absorption and append the result to the result
                    result.append(Expr('&', [Expr('~', [operand.operands[0]]), expr.operands[1]]))
                    break
            # If the current conjunction does not contain a negation, append it to the result
            else:
