def next_version(version):
    def next_non_zero_digit(digit):
        if digit == 9:
            return 0
        else:
            return digit + 1

    def next_non_zero_digit_index(version, start_index):
        for index in range(start_index, len(version)):
            if version[index] != 0:
                return index
        return None

    def digit_at(version, index):
        return version[index]

    def increment_version(version):
        non_zero_index = next_non_zero_digit_index(version, 0)
        if non_zero_index is None:
            version.insert(0, 1)
        else:
            non_zero_digit = digit_at(version, non_zero_index)
            next_digit = next_non_zero_digit(non_zero_digit)
            version[non_zero_index] = next_digit
            if next_digit == 0:
                for index in range(non_zero_index + 1, len(version)):
                    if version[index] != 0:
                        break
                else:
                    version.append(1)

        return version

    return '.'.join(str(s) for s in increment_version(version.split('.'))).strip()

def next_version(version):
    match = re.search(r'^(\d+)(\.?)(0*)$', version)
    if not match:
        raise ValueError("Invalid version string: " + version)
    major, dot, trailing_zeros = match.groups()
    if trailing_zeros:
        trailing_zeros = int(trailing_zeros)
    next_major = int(major) + 1
    if next_major >= 10:
        next_major = 0
        if dot:
            next_minor = 1
        else:
            next_minor = 0
    else:
        next_minor = trailing_zeros + 1
    return str(next_major) + str(next_minor)

