def paging(response, max_results):
    current_page = 0
    current_items = 0
    iterator = iter(response)
    while True:
        try:
            next_item = next(iterator)
            current_items += 1
            if current_items >= max_results:
                yield response[current_page * max_results : (current_page + 1) * max_results]
                current_page += 1
                current_items = 0
            continue
        except StopIteration:
