def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """

    if not isinstance(number, int):
        raise ValueError("number must be an integer")
    if not isinstance(alphabet, List):
        raise ValueError("alphabet must be a list of strings")
    if padding is not None and not isinstance(padding, int):
        raise ValueError("padding must be None or an integer")

    result = []
    while number > 0:
        result.append(alphabet[number % len(alphabet)])
        number //= len(alphabet)

    if padding is not None:
        result.extend(["0"] * padding)

    return "".join(reversed(result))

def int_to_string(number, alphabet, padding=None):
    if not isinstance(number, int):
        raise TypeError("number must be an integer")
    if not isinstance(alphabet, list):
        raise TypeError("alphabet must be a list")
    if padding is not None and not isinstance(padding, int):
        raise TypeError("padding must be an integer or None")

    if len(alphabet) == 0:
        raise ValueError("alphabet must have at least one element")

    if number < 0:
        raise ValueError("number must be non-negative")

    # Base case: if the number is 0, return the first letter of the alphabet
    if number == 0:
        return alphabet[0]

    # Recursive case: if the number is not 0, split it into two parts
    # The first part is equal to the number divided by the length of the alphabet, rounded down
    # The second part is equal to the number modulo the length of the alphabet
    first_part = number // len(alphabet)
    second_part = number % len(alphabet)

    # Convert the first part to a string using the same algorithm
    first_part_string = int_to_string(first_part, alphabet)

    # If the first part is empty, use the padding character if provided, or the first letter of the alphabet otherwise
    if len(first_part_string) == 0:
        if padding is not None:
            first_part_string = alphabet[padding]
        else:
            first_part_string = alphabet[0]

    # Add the second part to the first part, using the alphabet to convert the second part to a string
    return first_part_string + alphabet[second_part]

