    if platform == 'POSIX':
        regex = re.compile(r'(\w+(\|\w+)*|\"[A-Za-z0-9_\ \'\"]*\"|\'[A-Za-z0-9-_\ \']*\')')
        args = []
        for m in re.finditer(regex, s):
            if m.group()[0] in ["'", '"']:
                args.append(m.group()[1:-1])
            else:
                args.extend(re.split(r'\||', m.group()))
    elif platform == 'Windows/CMD':
        regex = re.compile(r'(\".*?\"|\'.*?\'|[^"\s]+)')
        args = [re.sub(r'^\'|\'$', '', re.sub(r'^"|\"$', '', m.group())) for m in re.finditer(regex, s)]
    else:
        raise ValueError('Unsupported platform: {}'.format(platform))

    return args

