    # First, make sure that the function is callable
    if not callable(func):
        raise ValueError("Invalid function passed in: {}".format(func))

    # Next, ensure that the timeout is a valid value
    if (timeout < 0) or (timeout > sys.getrecursionlimit()):
        raise ValueError("Invalid timeout value passed: {}".format(timeout))

    # Set up the command to be run
    cmd = [sys.executable, "-c", func.__module__ + "." + func.__name__ + "()"] + list(args)

    # Set up the environment variables
    env = os.environ
    if extra_env is not None:
        env.update(extra_env)

    # Run the command in a subprocess
    try:
        result = subprocess.run(cmd, timeout=timeout, env=env, check=True)
    except subprocess.CalledProcessError as e:
        raise ValueError("Function returned non-zero exit code: {}".format(e.returncode))

    # Return the result of the function
    return result.returncode, result.stdout.decode(), result.stderr.decode()

