def from_ticks(ticks, tz=None):
    if tz is None:
        tz = datetime.timezone.utc

    if ticks < 0 or ticks >= 86400000000000:
        raise ValueError("ticks is out of bounds (0 <= ticks < 86400000000000)")

    seconds, nanoseconds = divmod(ticks, 1000000000)
    microseconds = nanoseconds // 1000
    # Create a new time object from the given ticks and timezone
    return Time(seconds, microseconds, tz)

