@classmethod
def from_ticks(cls, ticks, tz=None):
    if not 0 <= ticks < 86400000000000:
        raise ValueError("ticks must be in the range [0, 86400000000000)")

    midnight = tz.midnight() if tz else datetime.time(0, 0, 0, 0) + datetime.datetime.now(tz).utcoffset()
    return Time(midnight + datetime.timedelta(seconds=ticks / 1e9), tz)

