    if not tentative and not iface.providedBy(candidate):
        raise zope.interface.Invalid("candidate {} was not marked as providing interface {}".format(candidate, iface))
    missing_methods = set(iface) - set(candidate)
    if missing_methods:
        raise zope.interface.Invalid("candidate {} is missing methods {}".format(candidate, missing_methods))
    missing_attributes = set(iface.names(all=True)) - set(candidate)
    if missing_attributes:
        raise zope.interface.Invalid("candidate {} is missing attributes {}".format(candidate, missing_attributes))
    for method, _type in iface.items():
        try:
