    """
    Resolves the include dict directive in the spec files.
    :param parser_dict: the parser dictionary to process
    """
    try:
        if parser_dict["include"]:
            for inc in parser_dict["include"]:
                try:
                    # resolve the path of the included file
                    rel_path = os.path.join(os.path.dirname(parser_dict["$filename$"]), inc)
                    path = os.path.abspath(rel_path)
                    # read the included file
                    with open(path, "r") as included_file:
                        included_lines = included_file.read()
                        # append the included lines to the end of the current parser dictionary
                        parser_dict.update(yaml.load(included_lines))
                except FileNotFoundError:
                    raise ValueError(f"Included file {path} not found")
        return parser_dict
    except KeyError:
        raise ValueError("Invalid input format: include key not found")

def _include_groups(self, parser_dict):
    # Step 1: Validate the input data
    if not isinstance(parser_dict, dict):
        raise TypeError("'parser_dict' must be a dictionary")

    # Step 2: Resolve the include dict directive
    for group, group_spec in parser_dict.items():
        if "include" not in group_spec:
            continue
        include_spec = group_spec["include"]
        if "groups" not in include_spec:
            raise ValueError("'include' directive must specify 'groups'")
        include_groups = include_spec["groups"]
        for include_group in include_groups:
            if include_group not in parser_dict:
                raise ValueError(f"Invalid include group: {include_group}")
            included_group_spec = parser_dict[include_group]
            for feature, feature_spec in included_group_spec.items():
                if feature not in group_spec:
                    group_spec[feature] = feature_spec

    return parser_dict

