def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    # Validate input parameters
    if not isinstance(cli_args, list) or not len(cli_args):
        raise ValueError("cli_args must be a non-empty list")
    if not isinstance(vars_dict, dict):
        raise ValueError("vars_dict must be a dictionary")
    if not isinstance(ir_workspace, Workspace):
        raise ValueError("ir_workspace must be a Workspace object")
    if not isinstance(ir_plugin, Plugin):
        raise ValueError("ir_plugin must be a Plugin object")

    # Set up Ansible CLI with our arguments
    ansible_cli_args = ("ansible-playbook",) + tuple(cli_args)

    # Pass extra vars to Ansible
    vars_dict["ir_workspace"] = ir_workspace
    vars_dict["ir_plugin"] = ir_plugin
    ansible_vars = "-e" + " ".join(f"{key}={value}" for key, value in vars_dict.items())

    # Run Ansible CLI
    try:
        ansible_stdout, ansible_stderr = Popen(ansible_cli_args + (ansible_vars,), stdout=PIPE, stderr=PIPE).communicate()
    except CalledProcessError as err:
        raise RuntimeError("Ansible CLI threw a CalledProcessError") from err

    # Format and return ansible results
    ansible_results = {
        "stdout": ansible_stdout.decode().strip(),
        "stderr": ansible_stderr.decode().strip(),
    }
    return ansible_results

